def count_divisors(n):
    count = 1
    d = 2
    temp = n
    while d * d <= temp:
        exponent = 0
        while temp % d == 0:
            exponent += 1
            temp //= d
        if exponent > 0:
            count *= (2 * exponent + 1)
        d += 1
    if temp > 1:
        count *= 3 # Since temp is a prime factor raised to power 1, 2*1 + 1 = 3
    return count

# Test the two candidates found
candidates = {
    1080: '2^3 * 3^2 * 5^1 * 7^1',
    1620: '2^2 * 3^3 * 5^1 * 7^1'
}

for x, factorization in candidates.items():
    tau_x2 = count_divisors(x)
    print(f"x={x} ({factorization}): tau(x^2) = {tau_x2}")
